mapper.select:
select a.article_code, a.legacy_path, c.category_code, c.category_name, r.title, r.summary, r.top_flag, r.published_at from site_article a inner join site_article_revision r on r.revision_id = a.published_revision_id left join site_article_category c on c.category_id = a.category_id where a.del_flag = '0' and r.revision_state = 'PUBLISHED'
and c.category_code = #{categoryCode}
order by r.top_flag desc, r.published_at desc, a.article_id desc limit #{limit}
